import Foundation

/// A clip as the tutorials' clip filter sees it (spec §11 TU-2 (3)): the five
/// keys a `needs`, a `selection` wait or a `$pick` may name, answered for one
/// clip of one snapshot.
///
/// `tools/proof/tutorial_probe.swift` answers these per clip of the bundled
/// practice project, so `tutorial_check.py` can hold every tutorial's `needs`
/// to it (TU-7); TU2's runner calls `matches(_:)` for its waits and picks.
struct TutorialClipFacts: Equatable {
    /// The filter's keys, in TU-2 (3)'s order; `dictionary` answers exactly these.
    static let keys = ["has_sound", "has_pixels", "kind", "follows_clip", "has_transition"]
    /// `kind`'s values: every `ClipSource` case name.
    static let kinds = ["media", "still", "image", "text", "shape", "graphic", "nest", "adjustment"]

    /// The clip has an `audio` group.
    let hasSound: Bool
    /// The clip has a `video` group and is not an adjustment clip (which grades
    /// what is behind it and draws nothing of its own).
    let hasPixels: Bool
    /// The `ClipSource` case name (`ClipSource.kindName`).
    let kind: String
    /// The previous clip on its track (by start, then id) exists and this clip
    /// starts at or before that clip's end.
    let followsClip: Bool
    /// The clip's `transition_in` is not null.
    let hasTransition: Bool

    init(clip: ClipSnapshot, in snapshot: ProjectSnapshot) {
        hasSound = clip.audio != nil
        if case .adjustment = clip.source {
            hasPixels = false
        } else {
            hasPixels = clip.video != nil
        }
        kind = clip.source.kindName
        let earlier = snapshot.clips.filter {
            $0.track == clip.track && $0.id != clip.id
                && ($0.start < clip.start || ($0.start == clip.start && $0.id < clip.id))
        }
        let previous = earlier.max { lhs, rhs in
            lhs.start != rhs.start ? lhs.start < rhs.start : lhs.id < rhs.id
        }
        if let previous {
            followsClip = clip.start <= previous.start + previous.duration
        } else {
            followsClip = false
        }
        hasTransition = clip.transitionIn != nil
    }

    /// The five keys and their values, as the filter spells them.
    var dictionary: [String: Any] {
        [
            "has_sound": hasSound,
            "has_pixels": hasPixels,
            "kind": kind,
            "follows_clip": followsClip,
            "has_transition": hasTransition,
        ]
    }

    /// Whether every key `filter` names holds here (`{}` matches any clip). A
    /// key outside `keys`, or a value of the wrong type, matches nothing.
    func matches(_ filter: [String: Any]) -> Bool {
        let mine = dictionary
        for (key, wanted) in filter {
            guard let have = mine[key] else { return false }
            if let have = have as? String {
                guard let wanted = wanted as? String, wanted == have else { return false }
            } else if let have = have as? Bool {
                guard let wanted = wanted as? Bool, wanted == have else { return false }
            } else {
                return false
            }
        }
        return true
    }
}
import Foundation

/// Where an inspector section lives: its tab and, on the Clip tab, its
/// sub-tab (nil on every other tab).
struct TutorialSectionHome: Equatable {
    let tab: InspectorTab
    let subTab: ClipSubTab?
}

/// The names a tutorial step may point at (spec §11 TU-2 (6)): the fixed
/// controls, every inspector section with its home, and the two clip
/// references. Nothing resolves a name to a view yet (TU3 does); the table is
/// what `tools/proof/tutorial_check.py` reads, through
/// `tools/proof/tutorial_probe.swift`'s `manifest()`, to refuse a guide page
/// that names a control the app does not have. The checker also fails when
/// `sections` and the section id literals in `app/Sources` differ.
enum TutorialTargets {
    static let sectionPrefix = "section:"
    static let clipPrefix = "clip:"
    static let clipRefs: [String] = ["$selection", "$created"]

    /// Every fixed name, and the control it names, one line each.
    static let fixed: [String: String] = {
        var names: [String: String] = [
            "timeline.clips": "the timeline's clip area",
            "ruler": "the timeline's ruler, where the playhead is dragged",
            "canvas": "the preview canvas",
            "toolbar.play": "the toolbar's Play button",
            "toolbar.timecode": "the toolbar's timecode readout",
            "toolbar.export": "the toolbar's Export… button",
            "timeline.bar.split": "the timeline bar's Split (scissors) button",
            "timeline.bar.trim_start": "the timeline bar's Trim Start button",
            "timeline.bar.trim_end": "the timeline bar's Trim End button",
            "timeline.bar.ripple_delete": "the timeline bar's Ripple Delete button",
            "timeline.bar.add_marker": "the timeline bar's Add Marker button",
            "timeline.bar.duplicate": "the timeline bar's Duplicate button",
            "timeline.bar.add_text": "the timeline bar's Add Text button",
            "timeline.bar.add_shape": "the timeline bar's Add Shape button",
            "sheet.export.format": "the export sheet's Format popup",
            "sheet.export.size": "the export sheet's Size popup",
            "sheet.export.frame_rate": "the export sheet's Frame rate popup",
            "sheet.export.quality": "the export sheet's Quality popup",
            "sheet.export.loudness": "the export sheet's Loudness popup",
            "sheet.export.range": "the export sheet's Range popup",
            "sheet.export.export": "the export sheet's Export… button",
            "sheet.export.add_to_queue": "the export sheet's Add to Queue button",
            "sheet.export.cancel": "the export sheet's Cancel button",
        ]
        for tab in InspectorTab.allCases {
            names["inspector.tab.\(tab.title.lowercased())"] = "the inspector's \(tab.title) tab"
        }
        for subTab in ClipSubTab.allCases {
            names["inspector.sub_tab.\(subTab.rawValue)"] =
                "the Clip tab's \(subTab.title) sub-tab"
        }
        return names
    }()

    /// Every `InspectorSection` id in `app/Sources` and where it lives:
    /// `ClipPane.makeSections()` for the Clip tab's sub-tabs (Shadow, built
    /// by `inspectorShadowSection`, on Picture), `DocumentPane` and
    /// `MediaPane` for theirs.
    static let sections: [String: TutorialSectionHome] = {
        var table: [String: TutorialSectionHome] = [:]
        func clip(_ subTab: ClipSubTab, _ ids: [String]) {
            for id in ids { table[id] = TutorialSectionHome(tab: .clip, subTab: subTab) }
        }
        func other(_ tab: InspectorTab, _ ids: [String]) {
            for id in ids { table[id] = TutorialSectionHome(tab: tab, subTab: nil) }
        }
        clip(.text, [
            "text.content", "text.font", "text.style", "text.outline", "text.backdrop",
            "text.box", "text.animation", "text.presets",
        ])
        clip(.shape, ["shape.kind", "shape.stroke", "shape.fill", "shape.gradient", "shape.arrows"])
        clip(.graphic, ["graphic.source", "graphic.properties", "graphic.size", "graphic.timeline"])
        clip(.picture, [
            "video.transform", "video.crop", "video.corner", "video.chroma", "video.shadow",
            "video.filters", "video.reflection", "video.spotlight", "video.obscure",
        ])
        clip(.color, [
            "video.adjustment", "video.qualifier", "video.light", "video.color", "video.wheels",
            "video.curves", "video.look",
        ])
        clip(.sound, [
            "audio.volume", "audio.fades", "audio.duck", "audio.noise", "audio.compressor",
            "audio.mix",
        ])
        clip(.clip, ["clip.timing", "video.speed", "video.transition", "video.motion"])
        other(.document, ["doc.summary", "doc.canvas", "doc.rate", "doc.appearance", "doc.markers"])
        other(.media, ["media.files", "media.camera_log", "media.hdr10"])
        return table
    }()

    /// The table as JSON-ready values, for the checker:
    /// `{"fixed": [sorted names], "sections": {id: {"tab", "sub_tab" | null}},
    /// "clip_refs", "tabs", "sub_tabs"}`, a tab by its title lowercased and a
    /// sub-tab by its raw value — the spellings a step's `reveal` uses.
    static func manifest() -> [String: Any] {
        var homes: [String: Any] = [:]
        for (id, home) in sections {
            homes[id] = [
                "tab": home.tab.title.lowercased(),
                "sub_tab": home.subTab.map { $0.rawValue as Any } ?? NSNull(),
            ] as [String: Any]
        }
        return [
            "fixed": fixed.keys.sorted(),
            "sections": homes,
            "clip_refs": clipRefs,
            "tabs": InspectorTab.allCases.map { $0.title.lowercased() },
            "sub_tabs": ClipSubTab.allCases.map(\.rawValue),
        ]
    }
}
import AppKit

#if FRAMEJOB_DEV_TOOLS
/// `select_inspector_tab` — a dev tool (road map 11's V3, spec §11 V-1..V-2):
/// pick the inspector's tab, and the Clip tab's sub-tab, in a project's
/// editor window, so `snapshot_ui` can capture what a click there shows.
///
/// **It goes through the clicks' own paths.** The tab is
/// `InspectorViewController.select(_:)`, which the tab strip calls; the
/// sub-tab is `selectClipSubTab(_:)`, which the sub-tab strip calls. Nothing
/// here writes the inspector's state any other way, so what is captured is
/// what a person's click would have drawn.
///
/// It runs on MAIN (not in `devOffMainTools`): it waits for nothing, and
/// every step is one AppKit call.
///
/// **Every refusal leaves the inspector as it was.** Arguments are read and
/// refused before anything moves; a sub-tab the selection does not have is
/// found only after the tab is picked (the Clip pane is in the view tree
/// only then), so that refusal is sent after the tab it found is picked
/// again; so is a `section` the shown pane does not hold, after which the tab
/// and the sub-tab it showed are picked again.
///
/// `section` (grading GR5b) scrolls the shown pane so that
/// section's top is the visible top, clamped — writing no preference and
/// opening nothing — and the answer says `look_thumbnails_pending` while a
/// Look gallery in the shown pane owes renders (spec §11 GR-7 [b]), which is
/// what a capture of its thumbnails waits out.
extension AgentServer {

    func selectInspectorTab(_ a: [String: Any]) throws -> String {
        let tabs = InspectorTab.allCases.map { $0.title.lowercased() }
        var tab: InspectorTab?
        if let raw = try stringArg(a, "tab") {
            guard let found = InspectorTab.allCases.first(where: { $0.title.lowercased() == raw })
            else {
                throw ToolError(
                    message: "tab must be one of \(tabs.joined(separator: ", ")) (got \"\(raw)\").")
            }
            tab = found
        }
        let sub = try enumArg(a, "sub_tab", ClipSubTab.self)
        let section = try stringArg(a, "section")
        if sub != nil, tab != .clip {
            throw ToolError(
                message: "sub_tab needs tab clip: the sub-tabs are the Clip tab's.")
        }

        let document = try target(a)
        guard let inspector = editor(document)?.inspector, inspector.isViewLoaded else {
            let name = Self.path(of: document) ?? document.displayName ?? "Untitled"
            throw ToolError(
                message: "The project \(name) has no window: select_inspector_tab reaches the "
                    + "inspector only through its editor window.")
        }
        let project = UISnapshot.orNull(Self.path(of: document))
        guard let tab else {
            if let section { try Self.scroll(inspector, to: section) }
            return try jsonResult(inspectorTabAnswer(inspector, project))
        }
        if sub != nil, inspector.selectedClips.isEmpty {
            throw ToolError(
                message: "sub_tab needs a selected clip: the Clip tab shows sub-tabs only for "
                    + "a selection (set_selection).")
        }

        let previous = inspector.tab
        let previousSub = previous == .clip ? Self.clipPane(in: inspector)?.activeSubTab : nil
        inspector.select(tab)
        if let sub {
            let offered = Self.clipPane(in: inspector)?.subTabs ?? []
            guard offered.contains(sub) else {
                inspector.select(previous)
                let names = offered.map(\.rawValue).joined(separator: ", ")
                throw ToolError(
                    message: "The selection has no \(sub.rawValue) sub-tab; its sub-tabs are "
                        + "\(names).")
            }
            inspector.selectClipSubTab(sub)
        }
        if let section {
            do {
                try Self.scroll(inspector, to: section)
            } catch {
                inspector.select(previous)
                if sub != nil, let previousSub { inspector.selectClipSubTab(previousSub) }
                throw error
            }
        }
        return try jsonResult(inspectorTabAnswer(inspector, project))
    }

    /// The scroll view the inspector shows its pane in, and that pane. Main
    /// thread.
    private static func shownPane(
        in inspector: InspectorViewController
    ) -> (NSScrollView, InspectorPaneView)? {
        var queue: [NSView] = [inspector.view]
        while !queue.isEmpty {
            let view = queue.removeFirst()
            if let scroll = view as? NSScrollView, let pane = scroll.documentView as? InspectorPaneView {
                return (scroll, pane)
            }
            queue.append(contentsOf: view.subviews)
        }
        return nil
    }

    /// Scrolls the shown pane so section `id`'s top is the visible top,
    /// clamped to the pane; refused, naming the sections it holds, when it
    /// holds no such section. Writes no preference and opens nothing.
    private static func scroll(_ inspector: InspectorViewController, to id: String) throws {
        let shown = shownPane(in: inspector)
        let sections = shown?.1.sections ?? []
        guard let (scroll, pane) = shown, let section = sections.first(where: { $0.id == id })
        else {
            let ids = sections.map(\.id)
            throw ToolError(
                message: "The shown pane has no section \(id); its sections are "
                    + (ids.isEmpty ? "none" : ids.joined(separator: ", ")) + ".")
        }
        inspector.view.layoutSubtreeIfNeeded()
        let clip = scroll.contentView
        let top = section.convert(section.bounds, to: pane).minY
        let bottom = max(0, pane.frame.height - clip.bounds.height)
        clip.scroll(to: NSPoint(x: 0, y: min(max(0, top), bottom)))
        scroll.reflectScrolledClipView(clip)
    }

    /// Whether a Look gallery in the shown pane owes renders. Main thread.
    private static func lookPending(in inspector: InspectorViewController) -> Bool {
        guard let pane = shownPane(in: inspector)?.1 else { return false }
        var queue: [NSView] = [pane]
        while !queue.isEmpty {
            let view = queue.removeFirst()
            if let gallery = view as? LookGalleryView, gallery.isPending { return true }
            queue.append(contentsOf: view.subviews)
        }
        return false
    }

    /// What the inspector shows now: the tab and, on the Clip tab with a
    /// selection, the active sub-tab and the ones on offer. Main thread.
    private func inspectorTabAnswer(
        _ inspector: InspectorViewController, _ project: Any
    ) -> [String: Any] {
        var sub: Any = NSNull()
        var offered: [String] = []
        if inspector.tab == .clip, !inspector.selectedClips.isEmpty,
            let pane = Self.clipPane(in: inspector)
        {
            sub = pane.activeSubTab.rawValue
            offered = pane.subTabs.map(\.rawValue)
        }
        var answer: [String: Any] = [
            "ok": true,
            "project": project,
            "tab": inspector.tab.title.lowercased(),
            "sub_tab": sub,
            "sub_tabs": offered,
        ]
        if Self.lookPending(in: inspector) { answer["look_thumbnails_pending"] = true }
        return answer
    }

    /// The Clip pane among the inspector's descendants — there only while the
    /// Clip tab shows it. Main thread.
    private static func clipPane(in inspector: InspectorViewController) -> ClipPane? {
        var queue: [NSView] = [inspector.view]
        while !queue.isEmpty {
            let view = queue.removeFirst()
            if let pane = view as? ClipPane { return pane }
            queue.append(contentsOf: view.subviews)
        }
        return nil
    }

    // MARK: - Catalog

    func selectInspectorTabTool() -> [String: Any] {
        tool(
            "select_inspector_tab",
            "DEV TOOL (absent from Distribution builds). Pick the inspector's tab, and the "
                + "Clip tab's sub-tab, in a project's editor window, through the same calls "
                + "the tab strip's and the sub-tab strip's clicks make — so snapshot_ui "
                + "captures what a click would show. With no tab, changes nothing and answers "
                + "what is shown. Answers the tab, and on the Clip tab with a selection the "
                + "active sub-tab and the sub-tabs on offer. Refused, changing nothing: a "
                + "sub_tab without tab clip, a sub_tab with no clip selected, and a sub_tab "
                + "the selection does not have (the refusal names the ones it has). The pick "
                + "is forgotten when the selection changes, as a click's is. section (with or "
                + "without tab) then scrolls the shown pane so that section's top is the visible "
                + "top, writing no preference and opening nothing; a section the pane does not "
                + "hold is refused naming the ones it holds, with the tab and sub-tab put back. "
                + "While a Look gallery in the shown pane is open and still owes thumbnails the "
                + "answer carries look_thumbnails_pending: true, absent otherwise.",
            [
                "tab": [
                    "type": "string",
                    "enum": InspectorTab.allCases.map { $0.title.lowercased() },
                    "description": "The inspector tab to show. Omit to change nothing and "
                        + "answer what is shown.",
                ],
                "sub_tab": [
                    "type": "string", "enum": ClipSubTab.allCases.map(\.rawValue),
                    "description": "With tab clip: the sub-tab to show. The selection "
                        + "decides which it has (text, shape, graphic, picture, sound, and "
                        + "clip always).",
                ],
                "section": [
                    "type": "string",
                    "description": "A section id in the shown pane (video.look, "
                        + "video.light, …) to scroll to the top of the inspector, after any "
                        + "tab and sub_tab pick.",
                ],
            ])
    }
}
#endif

