    /// "clip_refs", "tabs", "sub_tabs"}`, a tab by its title lowercased and a
    /// sub-tab by its raw value — the spellings a step's `reveal` uses.
    static func manifest() -> [String: Any] {
        var homes: [String: Any] = [:]
        for (id, home) in sections {
            homes[id] = [
                "tab": home.tab.title.lowercased(),
                "sub_tab": home.subTab.map { $0.rawValue as Any } ?? NSNull(),
            ] as [String: Any]
        }
        return [
            "fixed": fixed.keys.sorted(),
            "sections": homes,
            "clip_refs": clipRefs,
            "tabs": InspectorTab.allCases.map { $0.title.lowercased() },
            "sub_tabs": ClipSubTab.allCases.map(\.rawValue),
        ]
    }
}
import AppKit

#if FRAMEJOB_DEV_TOOLS
/// `select_inspector_tab` — a dev tool (road map 11's V3, spec §11 V-1..V-2):
/// pick the inspector's tab, and the Clip tab's sub-tab, in a project's
/// editor window, so `snapshot_ui` can capture what a click there shows.
///
/// **It goes through the clicks' own paths.** The tab is
/// `InspectorViewController.select(_:)`, which the tab strip calls; the
/// sub-tab is `selectClipSubTab(_:)`, which the sub-tab strip calls. Nothing
/// here writes the inspector's state any other way, so what is captured is
/// what a person's click would have drawn.
///
/// It runs on MAIN (not in `devOffMainTools`): it waits for nothing, and
/// every step is one AppKit call.
///
/// **Every refusal leaves the inspector as it was.** Arguments are read and
/// refused before anything moves; a sub-tab the selection does not have is
/// found only after the tab is picked (the Clip pane is in the view tree
/// only then), so that refusal is sent after the tab it found is picked
/// again; so is a `section` the shown pane does not hold, after which the tab
/// and the sub-tab it showed are picked again.
///
/// `section` (grading GR5b) scrolls the shown pane so that
/// section's top is the visible top, clamped — writing no preference and
/// opening nothing — and the answer says `look_thumbnails_pending` while a
/// Look gallery in the shown pane owes renders (spec §11 GR-7 [b]), which is
/// what a capture of its thumbnails waits out.
extension AgentServer {

    func selectInspectorTab(_ a: [String: Any]) throws -> String {
        let tabs = InspectorTab.allCases.map { $0.title.lowercased() }
        var tab: InspectorTab?
        if let raw = try stringArg(a, "tab") {
            guard let found = InspectorTab.allCases.first(where: { $0.title.lowercased() == raw })
            else {
                throw ToolError(
                    message: "tab must be one of \(tabs.joined(separator: ", ")) (got \"\(raw)\").")
            }
            tab = found
        }
        let sub = try enumArg(a, "sub_tab", ClipSubTab.self)
        let section = try stringArg(a, "section")
        if sub != nil, tab != .clip {
            throw ToolError(
                message: "sub_tab needs tab clip: the sub-tabs are the Clip tab's.")
        }

        let document = try target(a)
        guard let inspector = editor(document)?.inspector, inspector.isViewLoaded else {
            let name = Self.path(of: document) ?? document.displayName ?? "Untitled"
            throw ToolError(
                message: "The project \(name) has no window: select_inspector_tab reaches the "
                    + "inspector only through its editor window.")
        }
        let project = UISnapshot.orNull(Self.path(of: document))
        guard let tab else {
            if let section { try Self.scroll(inspector, to: section) }
            return try jsonResult(inspectorTabAnswer(inspector, project))
        }
        if sub != nil, inspector.selectedClips.isEmpty {
            throw ToolError(
                message: "sub_tab needs a selected clip: the Clip tab shows sub-tabs only for "
                    + "a selection (set_selection).")
        }

        let previous = inspector.tab
        let previousSub = previous == .clip ? Self.clipPane(in: inspector)?.activeSubTab : nil
        inspector.select(tab)
        if let sub {
            let offered = Self.clipPane(in: inspector)?.subTabs ?? []
            guard offered.contains(sub) else {
                inspector.select(previous)
                let names = offered.map(\.rawValue).joined(separator: ", ")
                throw ToolError(
                    message: "The selection has no \(sub.rawValue) sub-tab; its sub-tabs are "
                        + "\(names).")
            }
            inspector.selectClipSubTab(sub)
        }
        if let section {
            do {
                try Self.scroll(inspector, to: section)
            } catch {
                inspector.select(previous)
                if sub != nil, let previousSub { inspector.selectClipSubTab(previousSub) }
                throw error
            }
        }
        return try jsonResult(inspectorTabAnswer(inspector, project))
    }

    /// The scroll view the inspector shows its pane in, and that pane. Main
    /// thread.
    private static func shownPane(
        in inspector: InspectorViewController
    ) -> (NSScrollView, InspectorPaneView)? {
        var queue: [NSView] = [inspector.view]
        while !queue.isEmpty {
            let view = queue.removeFirst()
            if let scroll = view as? NSScrollView, let pane = scroll.documentView as? InspectorPaneView {
                return (scroll, pane)
            }
            queue.append(contentsOf: view.subviews)
        }
        return nil
    }

    /// Scrolls the shown pane so section `id`'s top is the visible top,
    /// clamped to the pane; refused, naming the sections it holds, when it
    /// holds no such section. Writes no preference and opens nothing.
    private static func scroll(_ inspector: InspectorViewController, to id: String) throws {
        let shown = shownPane(in: inspector)
        let sections = shown?.1.sections ?? []
        guard let (scroll, pane) = shown, let section = sections.first(where: { $0.id == id })
        else {
            let ids = sections.map(\.id)
            throw ToolError(
                message: "The shown pane has no section \(id); its sections are "
                    + (ids.isEmpty ? "none" : ids.joined(separator: ", ")) + ".")
        }
        inspector.view.layoutSubtreeIfNeeded()
        let clip = scroll.contentView
        let top = section.convert(section.bounds, to: pane).minY
        let bottom = max(0, pane.frame.height - clip.bounds.height)
        clip.scroll(to: NSPoint(x: 0, y: min(max(0, top), bottom)))
        scroll.reflectScrolledClipView(clip)
    }

    /// Whether a Look gallery in the shown pane owes renders. Main thread.
    private static func lookPending(in inspector: InspectorViewController) -> Bool {
        guard let pane = shownPane(in: inspector)?.1 else { return false }
        var queue: [NSView] = [pane]
        while !queue.isEmpty {
            let view = queue.removeFirst()
            if let gallery = view as? LookGalleryView, gallery.isPending { return true }
            queue.append(contentsOf: view.subviews)
        }
        return false
    }

    /// What the inspector shows now: the tab and, on the Clip tab with a
    /// selection, the active sub-tab and the ones on offer. Main thread.
    private func inspectorTabAnswer(
        _ inspector: InspectorViewController, _ project: Any
    ) -> [String: Any] {
        var sub: Any = NSNull()
        var offered: [String] = []
        if inspector.tab == .clip, !inspector.selectedClips.isEmpty,
            let pane = Self.clipPane(in: inspector)
        {
            sub = pane.activeSubTab.rawValue
            offered = pane.subTabs.map(\.rawValue)
        }
        var answer: [String: Any] = [
            "ok": true,
            "project": project,
            "tab": inspector.tab.title.lowercased(),
            "sub_tab": sub,
            "sub_tabs": offered,
        ]
        if Self.lookPending(in: inspector) { answer["look_thumbnails_pending"] = true }
        return answer
    }

    /// The Clip pane among the inspector's descendants — there only while the
    /// Clip tab shows it. Main thread.
    private static func clipPane(in inspector: InspectorViewController) -> ClipPane? {
        var queue: [NSView] = [inspector.view]
        while !queue.isEmpty {
            let view = queue.removeFirst()
            if let pane = view as? ClipPane { return pane }
            queue.append(contentsOf: view.subviews)
        }
        return nil
    }

    // MARK: - Catalog

    func selectInspectorTabTool() -> [String: Any] {
        tool(
            "select_inspector_tab",
            "DEV TOOL (absent from Distribution builds). Pick the inspector's tab, and the "
                + "Clip tab's sub-tab, in a project's editor window, through the same calls "
                + "the tab strip's and the sub-tab strip's clicks make — so snapshot_ui "
                + "captures what a click would show. With no tab, changes nothing and answers "
                + "what is shown. Answers the tab, and on the Clip tab with a selection the "
                + "active sub-tab and the sub-tabs on offer. Refused, changing nothing: a "
                + "sub_tab without tab clip, a sub_tab with no clip selected, and a sub_tab "
                + "the selection does not have (the refusal names the ones it has). The pick "
                + "is forgotten when the selection changes, as a click's is. section (with or "
                + "without tab) then scrolls the shown pane so that section's top is the visible "
                + "top, writing no preference and opening nothing; a section the pane does not "
                + "hold is refused naming the ones it holds, with the tab and sub-tab put back. "
                + "While a Look gallery in the shown pane is open and still owes thumbnails the "
                + "answer carries look_thumbnails_pending: true, absent otherwise.",
            [
                "tab": [
                    "type": "string",
                    "enum": InspectorTab.allCases.map { $0.title.lowercased() },
                    "description": "The inspector tab to show. Omit to change nothing and "
                        + "answer what is shown.",
                ],
                "sub_tab": [
                    "type": "string", "enum": ClipSubTab.allCases.map(\.rawValue),
                    "description": "With tab clip: the sub-tab to show. The selection "
                        + "decides which it has (text, shape, graphic, picture, sound, and "
                        + "clip always).",
                ],
                "section": [
                    "type": "string",
                    "description": "A section id in the shown pane (video.look, "
                        + "video.light, …) to scroll to the top of the inspector, after any "
                        + "tab and sub_tab pick.",
                ],
            ])
    }
}
#endif

content.content:
import AppKit

/// The inspector panel (spec §4.3): the tab strip and the scroll view that
/// hosts one pane at a time.
///
/// **Frozen at wiring**, like `EditorViewController` and `TimelineView`: the
/// controls live in the pane files and the shared pieces in
/// `InspectorPane.swift`. What this file owns is the policy —
///
///  - a PICKED clip shows the Clip tab, because that is what the user just
///    asked about — `clipPicked()` for a click (which switches even when the
///    click re-picks the clip that was already selected) and, on top of it, a
///    selection that changed under an unrelated path (paste, ⌘A, the agent),
///    from the Media and Document tabs only — the Assistant tab stays, since
///    the assistant's own calls change the selection mid-turn (spec §11 AI-14);
///  - a pane is REBUILT only when the model's shape changes
///    (`structureSignature`) and merely refreshed otherwise, so a live canvas
///    drag updates every field without tearing down the control the user is
///    holding.
///
/// The policy used to be three times this size — a tab was disabled when no
/// selected clip had that aspect, a new selection picked the most relevant
/// enabled tab, and a pin existed to defeat that pick. Four tabs, all always
/// live, retire all of it: which SECTIONS the Clip tab shows is now
/// `ClipPane.makeSections()`'s answer, and there is nothing left for a pin to
/// protect.
///
/// Edits leave through the `on*` closures, wired in
/// `EditorViewController+Inspector.swift`; nothing here touches
/// `ProjectDocument` directly except to READ it.
final class InspectorViewController: NSViewController {
    // MARK: - Model

    /// Read-only from here: every write goes out through the closures below,
    /// so `ProjectDocument` stays the single mutation point.
    weak var document: ProjectDocument?

    lazy var binding = InspectorBinding(inspector: self)

    // MARK: - Intent out

    var onEdit: ((String, [ReelOp]) -> Void)?
    /// For commits made outside an AppKit event (a sheet or alert's
    /// completion) — `ProjectDocument.performGroupedEdit`.
    var onGroupedEdit: ((String, [ReelOp]) -> Void)?
    /// `onEdit` as one undo step with the step that ended at the handle
    /// given — a wheel strip's double-click off the knob (#272) —
    /// `ProjectDocument.applyEdit(_:_:amending:)`.
    var onAmendEdit: ((String, [ReelOp], ReelProject) -> Void)?
    var onLiveBegin: (() -> Void)?
    var onLiveUpdate: (([ReelOp]) -> Void)?
    var onLiveEnd: ((String) -> Void)?
    /// Files dropped on the Media tab, or picked by Add Media….
    var onImportFiles: (([URL]) -> Void)?
    /// A PURE trial application, for learning an id the core is about to mint
    /// (the new track a canvas drop needs). Never an edit.
    var onProbe: (([ReelOp]) -> ProjectSnapshot?)?
    /// Jump the playhead — the markers list and the actions table.
    var onSeek: ((Ticks) -> Void)?
    /// Hand a command back to the editor (Crop on Canvas, Detach Audio).
    var onCommand: ((Selector) -> Void)?
    /// Select an action of the single selected clip, or nil to leave the mode.
    var onSelectAction: ((UInt32?) -> Void)?
    /// The Assistant tab's view, the moment `AssistantPane` builds it.
    var onAssistantView: ((AssistantView) -> Void)?

    // MARK: - State

    private(set) var tab: InspectorTab = .clip

    private var tabsContainer: NSView!
    private var tabsView: PanelTabsView?
    /// The previous strip, held one generation past its removal — the pitfall
    /// is named in `buildTabs()`.
    private var retiredTabs: PanelTabsView?
    /// The pane's pinned block, above the scroll view (spec §11 CI-5).
    private let pinnedContainer = NSStackView()
    /// The previous block, held one generation — `buildTabs()`'s pitfall.
    private var retiredPinned: NSView?
    /// The foot under the scroll view and the refusal strip it hosts (CI-10).
    let footContainer = NSStackView()
    let refusalStrip = InspectorRefusalStrip()
    /// The Assistant tab's question dot, over the strip (spec §11 AI-19).
    let assistantBadge = InspectorTabBadge()
    private var scroll: NSScrollView!
    private var panes: [InspectorTab: InspectorPaneView] = [:]
    private var currentPane: InspectorPaneView?
    private var lastSelection: [UInt32] = []
    private var lastSignature: String?

    // MARK: - Life cycle

    init() {
        super.init(nibName: nil, bundle: nil)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorViewController does not support NSCoder")
    }

    override func loadView() {
        let root = NSView(frame: NSRect(x: 0, y: 0, width: 320, height: 640))
        root.wantsLayer = true
        root.layer?.backgroundColor = DS.chromeBackground.cgColor

        // `PanelTabsView` fixes its active tab at init (Controls.swift is
        // carried from Rasterize and is not forked here), so the strip is
        // rebuilt inside this container whenever the tab changes.
        tabsContainer = NSView()
        tabsContainer.translatesAutoresizingMaskIntoConstraints = false
        root.addSubview(tabsContainer)

        pinnedContainer.orientation = .vertical
        pinnedContainer.spacing = 0
        pinnedContainer.translatesAutoresizingMaskIntoConstraints = false
        root.addSubview(pinnedContainer)
        // Empty is 0 pt; a block's own rows say how tall it is.
        let collapse = pinnedContainer.heightAnchor.constraint(equalToConstant: 0)
        collapse.priority = NSLayoutConstraint.Priority(1)

        scroll = NSScrollView()
        scroll.contentView = InspectorClipView()
        scroll.translatesAutoresizingMaskIntoConstraints = false
        scroll.hasVerticalScroller = true
        scroll.autohidesScrollers = true
        scroll.drawsBackground = false
        scroll.borderType = .noBorder
        root.addSubview(scroll)
        footContainer.translatesAutoresizingMaskIntoConstraints = false
        footContainer.addArrangedSubview(refusalStrip)
        footContainer.orientation = .vertical
        root.addSubview(footContainer)
        let footCollapse = footContainer.heightAnchor.constraint(equalToConstant: 0)
        footCollapse.priority = NSLayoutConstraint.Priority(1)

        NSLayoutConstraint.activate([
            tabsContainer.topAnchor.constraint(equalTo: root.topAnchor),
            tabsContainer.leadingAnchor.constraint(equalTo: root.leadingAnchor),
            tabsContainer.trailingAnchor.constraint(equalTo: root.trailingAnchor),
            tabsContainer.heightAnchor.constraint(equalToConstant: DS.tabHeight),
            pinnedContainer.topAnchor.constraint(equalTo: tabsContainer.bottomAnchor),
            pinnedContainer.leadingAnchor.constraint(equalTo: root.leadingAnchor),
            pinnedContainer.trailingAnchor.constraint(equalTo: root.trailingAnchor),
            collapse,
            scroll.topAnchor.constraint(equalTo: pinnedContainer.bottomAnchor),
            scroll.leadingAnchor.constraint(equalTo: root.leadingAnchor),
            scroll.trailingAnchor.constraint(equalTo: root.trailingAnchor),
            scroll.bottomAnchor.constraint(equalTo: footContainer.topAnchor),
            footContainer.leadingAnchor.constraint(equalTo: root.leadingAnchor),
            footContainer.trailingAnchor.constraint(equalTo: root.trailingAnchor),
            footContainer.bottomAnchor.constraint(equalTo: root.bottomAnchor),
            footCollapse,
        ])
        assistantBadge.install(over: tabsContainer, in: root)
        view = root
        buildTabs()
    }

    override func viewDidLoad() {
        super.viewDidLoad()
        refresh(isLive: false)
    }

    // MARK: - Selection

    /// The selected clips in timeline order — what every pane edits.
    var selectedClips: [ClipSnapshot] {
        guard let document = document else { return [] }
        let ids = document.selection
        return document.editedProject.snapshot.clips.filter { ids.contains($0.id) }
            .sorted { $0.start < $1.start }
    }

    // MARK: - Tabs

    private func buildTabs() {
        // **Pitfall:** this usually runs from inside the OUTGOING strip's own
        // `mouseDown` — a tab click calls `onSelect`, which lands here — and
        // `tabsView` plus the superview are that view's only strong
        // references. Dropping both mid-event would deallocate the view the
        // window is still dispatching the event to. Held one generation, for
        // the same reason and in the same shape as
        // `InspectorPaneView.rebuild()`'s `retired`; the NEXT build releases
        // it, which is never inside its event.
        retiredTabs = tabsView
        tabsView?.removeFromSuperview()
        let strip = PanelTabsView(
            titles: InspectorTab.allCases.map { $0.title }, activeIndex: tab.rawValue,
            onSelect: { [weak self] index in self?.tabPicked(index) })
        strip.translatesAutoresizingMaskIntoConstraints = false
        tabsContainer.addSubview(strip)
        NSLayoutConstraint.activate([
            strip.topAnchor.constraint(equalTo: tabsContainer.topAnchor),
            strip.bottomAnchor.constraint(equalTo: tabsContainer.bottomAnchor),
            strip.leadingAnchor.constraint(equalTo: tabsContainer.leadingAnchor),
            strip.trailingAnchor.constraint(equalTo: tabsContainer.trailingAnchor),
        ])
        tabsView = strip
    }

    private func tabPicked(_ index: Int) {
        guard let picked = InspectorTab(rawValue: index) else { return }
        select(picked)
    }

    /// Programmatic tab selection, and the only writer of `tab`. `clipPicked()`
    /// is its one caller besides the strip itself; the "show me the Media tab
    /// after Add Media…" this comment used to promise has never had a call
    /// site, and is not worth inventing one for — the import lands rows in a
    /// tab the user can already see.
    func select(_ next: InspectorTab) {
        guard tab != next else { return }
        tab = next
        buildTabs()
        refresh(isLive: false)
    }

    /// "The user just picked a clip" — called by the timeline's and the
    /// canvas's click handlers AFTER they have written the new selection.
    ///
    /// The handoff's rule is unconditional: "Clicking a clip selects it,
    /// switches the inspector to the Clip tab". `refresh(isLive:)` cannot
    /// implement that on its own, because a re-click of the ALREADY selected
    /// clip looks exactly like every unrelated refresh — an edit, a playhead
    /// move, an agent op — and switching on those would make the Media and
    /// Document tabs unusable, since almost anything the user did there would
    /// throw them back to Clip. So the pick says so out loud, and the refresh
    /// keeps its own narrower rule for a selection that actually CHANGED
    /// (paste, ⌘A, the agent's `set_selection`).
    ///
    /// Empty selections are ignored: clicking bare lane deselects, and a Clip
    /// tab reading "Select a clip to edit its properties" is not what the user
    /// asked to see.
    func clipPicked() {
        guard isViewLoaded, !selectedClips.isEmpty else { return }
        select(.clip)
    }

    /// A Clip sub-tab was picked (`ClipSubTabsView`): the one refresh for it.
    func selectClipSubTab(_ tab: ClipSubTab) {
        (pane(for: .clip) as? ClipPane)?.choose(tab)
        refresh(isLive: false)
        scrollToTop()
    }

    /// Hosts the pane's pinned block. The outgoing one is held a generation:
    /// a sub-tab click lands inside the block's own `mouseDown`.
    private func installPinned(_ block: NSView?) {
        guard pinnedContainer.arrangedSubviews.first !== block else { return }
        retiredPinned = pinnedContainer.arrangedSubviews.first
        retiredPinned?.removeFromSuperview()
        guard let block else { return }
        pinnedContainer.addArrangedSubview(block)
        block.widthAnchor.constraint(equalTo: pinnedContainer.widthAnchor).isActive = true
    }

    private func pane(for tab: InspectorTab) -> InspectorPaneView {
        if let existing = panes[tab] { return existing }
        let made: InspectorPaneView
        switch tab {
        case .clip: made = ClipPane(inspector: self)
        case .media: made = MediaPane(inspector: self)
        case .document: made = DocumentPane(inspector: self)
        case .assistant: made = AssistantPane(inspector: self)
        }
        panes[tab] = made
        return made
    }

    /// Swaps the scroll view's document view, answering whether it actually
    /// swapped. A pane keeps its instance — and so its controls and its
    /// disclosure state — for the panel's life; the scroll POSITION belongs to
    /// the one scroll view, and `refresh(isLive:)` sends it back to the top
    /// whenever the pane under it changes.
    private func showPane(_ next: InspectorPaneView) -> Bool {
        guard currentPane !== next else { return false }
        currentPane = next
        next.translatesAutoresizingMaskIntoConstraints = false
        scroll.documentView = next
        NSLayoutConstraint.activate([
            next.topAnchor.constraint(equalTo: scroll.contentView.topAnchor),
            next.leadingAnchor.constraint(equalTo: scroll.contentView.leadingAnchor),
            next.widthAnchor.constraint(equalTo: scroll.contentView.widthAnchor),
            // Fills the visible area even when the sections are short, so the
            // panel has one background and the Media tab's drop target is the
            // whole pane rather than just its rows.
            next.heightAnchor.constraint(greaterThanOrEqualTo: scroll.contentView.heightAnchor),
        ])
        // A pane that was never shown has no rows yet; forcing the signature
        // to differ makes the refresh below build it.
        lastSignature = nil
        return true
    }

    /// Back to the top of the panel.
    ///
    /// Deliberately NOT called after every rebuild: a rebuild also happens
    /// when a filter is added, an action appears or a transition comes and
    /// goes, and yanking the panel to the top under a user who is dialling a
    /// filter halfway down it would trade one bug for another. The two moments
    /// the design names — a different clip, a different tab — are the two that
    /// ask for it.
    ///
    /// The pane is flipped (`InspectorPaneView.isFlipped`), so the top is
    /// y = 0 whatever the content height is, and this needs no layout pass to
    /// have run first.
    private func scrollToTop() {
        scroll.contentView.scroll(to: .zero)
        scroll.reflectScrolledClipView(scroll.contentView)
    }

    // MARK: - Refresh

    /// The ONE path from a changed document to the panel, called by
    /// `EditorViewController.refreshFromDocument`. `isLive` suppresses
    /// rebuilds: mid-gesture the values change but the shape does not.
    func refresh(isLive: Bool) {
        guard isViewLoaded else { return }
        refusalStrip.clearIfStale(document?.editedProject)
        binding.invalidate()
        let clips = selectedClips

        // Picking a clip in the timeline or on the canvas asks about THAT
        // clip, so the panel answers about it — one selection model, and the
        // panel is one of its three views (the timeline bar's block and the
        // canvas handles are the others).
        // Switched in place rather than through `select(_:)`: that one starts
        // a refresh of its own, and this one is already running — with
        // `isLive` in hand, which a nested call would drop.
        let ids = clips.map { $0.id }
        // A different clip and a different tab are the two things that make
        // the panel a different list, so they are the two that send it back to
        // the top; everything else leaves the user where they were reading.
        var toTop = false
        if ids != lastSelection {
            lastSelection = ids
            toTop = true
            (pane(for: .clip) as? ClipPane)?.forgetSubTab()
            if !clips.isEmpty, tab == .media || tab == .document {  // AI-14
                tab = .clip
                buildTabs()
            }
        }

        let pane = pane(for: tab)
        if showPane(pane) { toTop = true }
        let signature = pane.structureSignature
        // A rebuild replaces every control, so it must never happen under a
        // live gesture — the slider being dragged would vanish mid-drag.
        if signature != lastSignature, !isLive, document?.isLiveEditing != true {
            lastSignature = signature
            pane.rebuild()
            installPinned(pane.pinnedBlock)
        }
        pane.refresh()
        if toTop { scrollToTop() }
    }
}
import AppKit

// MARK: - Sections

/// One disclosure group: a header with the title, a right-aligned summary of
/// what the group currently says, an optional reset-to-default button, and the
/// rows. Collapsed state is per section id in `UserDefaults`, so a pane
/// rebuilt after every edit does not keep re-opening a group the user closed.
///
/// **The stored value records COLLAPSED, not expanded** — a section nobody has
/// touched has no stored value at all, which is what lets `defaultExpanded`
/// mean anything. Flipping that spelling would invert every saved panel.
final class InspectorSection: NSView {
    /// `UserDefaults` key prefix; the suffix is the section's stable id.
    static let collapsedKeyPrefix = "FrameJobInspectorSection."

    let id: String
    let title: String
    let header = InspectorSectionHeader()
    private let content = NSStackView()
    private(set) var isExpanded = true
    private let summary: (() -> String?)?
    /// An explicit "differs from its default" (spec §11 CI-9), for a section
    /// whose rows do not read the props or whose Reset writes fewer keys
    /// than its rows read; nil folds the rows' own defaults.
    private let differs: (() -> Bool)?
    /// The rows' marks, folded (road map 9 §5) at the end of `init` and on
    /// every `refresh()`.
    private(set) var marks = SectionMarks.empty
    /// "Actions don't animate this" — shown while every row that writes is ⊘.
    private var inertNote: InspectorNoteLabel?
    /// The header's click, after the preference is stored — and nothing else:
    /// `reveal()` and `expandByDefault()` never call it (`KeyedReveal`).
    var didToggle: ((InspectorSection) -> Void)?

    /// `summary` is a closure rather than a string because it is re-read on
    /// every `refresh()`: a collapsed section still has to tell the truth
    /// about the value under it. `defaultExpanded` is the state before the
    /// user has ever touched THIS section — the design opens Transform and
    /// the primary section of a text or shape selection, and closes the rest.
    init(
        id: String, title: String, summary: (() -> String?)? = nil,
        note: (() -> String?)? = nil, reset: (() -> Void)? = nil,
        differs: (() -> Bool)? = nil, defaultExpanded: Bool = true, rows: [NSView]
    ) {
        self.id = id
        self.title = title
        self.summary = summary
        self.differs = differs
        super.init(frame: .zero)
        let key = Self.collapsedKeyPrefix + id
        if let collapsed = UserDefaults.standard.object(forKey: key) as? Bool {
            isExpanded = !collapsed
        } else {
            isExpanded = defaultExpanded
        }

        content.orientation = .vertical
        content.alignment = .leading
        content.spacing = InspectorMetrics.rowSpacing
        content.edgeInsets = NSEdgeInsets(
            top: 2, left: InspectorMetrics.inset, bottom: 8, right: InspectorMetrics.inset)
        let inert = InspectorNoteLabel { [weak self] in
            self?.marks.allNotAnimatable == true
                ? "Actions don't animate this. Edits here change the clip." : nil
        }
        inert.textColor = DS.textFaint
        inertNote = inert
        addRow(inert)
        if let note = note {
            addRow(InspectorNoteLabel(note: note))
        }
        for row in rows { addRow(row) }

        header.configure(title: title, reset: reset, clear: { [weak self] in self?.clear() })
        header.onToggle = { [weak self] in self?.toggle() }

        let stack = NSStackView(views: [header, content])
        stack.orientation = .vertical
        stack.alignment = .leading
        stack.spacing = 0
        stack.translatesAutoresizingMaskIntoConstraints = false
        addSubview(stack)
        NSLayoutConstraint.activate([
            stack.topAnchor.constraint(equalTo: topAnchor),
            stack.bottomAnchor.constraint(equalTo: bottomAnchor),
            stack.leadingAnchor.constraint(equalTo: leadingAnchor),
            stack.trailingAnchor.constraint(equalTo: trailingAnchor),
            header.widthAnchor.constraint(equalTo: stack.widthAnchor),
            content.widthAnchor.constraint(equalTo: stack.widthAnchor),
        ])
        content.isHidden = !isExpanded
        header.isExpanded = isExpanded
        for gutter in Self.gutters(in: content) { gutter.refresh() }
        foldMarks()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorSection does not support NSCoder")
    }

    private func addRow(_ row: NSView) {
        content.addArrangedSubview(row)
        row.widthAnchor.constraint(
            equalTo: content.widthAnchor, constant: -2 * InspectorMetrics.inset).isActive = true
    }

    private func toggle() {
        isExpanded.toggle()
        // The redesign's one animation (spec §11 CI-15): through `DS.animate`,
        // which runs it unanimated under Reduce Motion. The state is set at once.
        DS.animate(DS.stateDuration) {
            content.isHidden = !isExpanded
            superview?.layoutSubtreeIfNeeded()
        }
        header.isExpanded = isExpanded
        UserDefaults.standard.set(!isExpanded, forKey: Self.collapsedKeyPrefix + id)
        didToggle?(self)
    }

    /// Opens the section and writes NO preference — the selected action's
    /// auto-open (spec §11 CI-8), which must leave the person's own layout
    /// standing for when the action is left.
    func reveal() {
        isExpanded = true
        content.isHidden = false
        header.isExpanded = true
    }

    /// Opens the section as a DEFAULT, for a pane that decided after building
    /// it that this is the group to open (`ClipPane`'s "the first section is
    /// open when there is no Transform"). `defaultExpanded` cannot say it: the
    /// pane only knows which section is first once it has them all.
    ///
    /// **It defers to the user and writes nothing.** A section the user has
    /// ever toggled has a stored value, and re-opening a group somebody closed
    /// on every rebuild would be worse than the closed panel this fixes;
    /// storing the state here would then make that override permanent.
    /// Returns whether it opened the section, so a caller walking a list can
    /// stop at the first one that had no stored preference.
    @discardableResult
    func expandByDefault() -> Bool {
        guard UserDefaults.standard.object(forKey: Self.collapsedKeyPrefix + id) == nil,
              !isExpanded
        else { return false }
        isExpanded = true
        content.isHidden = false
        header.isExpanded = true
        return true
    }

    func refresh() {
        refreshOptionControls(in: content)
        foldMarks()
    }

    /// The header's Clear (spec §11 CI-9): every key the section's rows
    /// write that the selected action holds, out of its end patch in ONE
    /// `set_action_end`.
    func clear() {
        let gutters = Self.gutters(in: content)
        guard let binding = gutters.lazy.compactMap({ $0.binding }).first else { return }
        let keys = gutters.reduce(into: Set<String>()) { $0.formUnion($1.keyedWrites()) }
        binding.apply("Clear", binding.clearOps(keys))
    }

    /// The rows' gutters, in the order `refreshOptionControls(in:)` walks.
    private static func gutters(in view: NSView) -> [InspectorMarkGutter] {
        view.subviews.flatMap { subview -> [InspectorMarkGutter] in
            if let gutter = subview as? InspectorMarkGutter { return [gutter] }
            return gutters(in: subview)
        }
    }

    /// `marks` from the gutters as they stand, then the two things drawn from
    /// it: the ⊘ note and the header. A section is EDITING the selected
    /// action when any of its rows animates; one that none does (Document,
    /// Shape, a ⊘-only section) keeps its Reset, since its edits go to the
    /// clip.
    private func foldMarks() {
        let gutters = Self.gutters(in: content)
        let writing = gutters.filter { !$0.writes.isEmpty }
        let binding = gutters.lazy.compactMap { $0.binding }.first
        marks = SectionMarks(
            keyed: gutters.reduce(into: Set<String>()) { $0.formUnion($1.keyedWrites()) }.count,
            other: gutters.contains {
                if case .other = $0.mark { return true } else { return false }
            },
            allNotAnimatable: !writing.isEmpty
                && writing.allSatisfy { $0.mark == .notAnimatable },
            differs: differs?() ?? gutters.contains { $0.default?.differs() == true },
            editing: gutters.contains { $0.animates } ? binding?.selectedActionNumber : nil)
        inertNote?.refresh()
        header.refresh(summary: summary?(), marks: marks)
    }
}

/// The auto-open (spec §11 CI-8): the sections the selected action keys are
/// revealed on the sub-tab showing them, remembered for as long as that
/// action stays selected — so a rebuild under the same action re-reveals
/// them, a sub-tab first shown later adds its own, and a header click that
/// closes one drops it. One per `ClipPane`, applied at the end of every
/// `makeSections()`; it lives here because `ClipPane.swift` is at its cap.
final class KeyedReveal {
    private(set) var action: UInt32?
    private(set) var seen: Set<String> = []
    private(set) var ids: Set<String> = []

    func apply(_ sections: [InspectorSection], action: UInt32?, subTab: String) {
        guard let action else {
            (self.action, seen, ids) = (nil, [], [])
            return
        }
        if action != self.action { (self.action, seen, ids) = (action, [], []) }
        if !seen.contains(subTab) {
            seen.insert(subTab)
            ids.formUnion(sections.filter { $0.marks.keyed > 0 }.map(\.id))
        }
        for section in sections {
            section.didToggle = { [weak self] in self?.ids.remove($0.id) }
            if ids.contains(section.id) { section.reveal() }
        }
    }
}

