/// arithmetic on a long take, which main must not be doing (SY-22). Each
/// hops back through `onMain` for every
/// document touch, so the single-mutation-point rule is untouched.
///
/// The criterion is NOT "touches the disk", which is why
/// `detect_silence`, `consolidate_media`, `import_captions` and
/// `export_captions` are all absent: each reads or writes a file on the
/// main thread and each says so in its own handler.
private static let productOffMainTools: Set<String> = [
    "import_media", "relink_media", "render_frame", "export", "save_project", "new_project",
    "transcribe", "record_screen", "render_graphic", "open_project", "sync_audio",
    "transcribe_for_fillers", "get_transcript", "export_graphic",
]
// The dev tools' members join here (AgentServer+DevTools.swift).
static let offMainTools = productOffMainTools.union(devOffMainTools)

// MARK: - Lifecycle

/// Builds the catalog, fills the gate and runs the parity check, once per
/// launch (spec §11 AI-3): `AgentLane.prepareAtLaunch()` calls it from
/// `main.swift`, and `bindSocket()` gets the memoised string. Main only; a
/// throw is not memoised.
@discardableResult
func prepareCatalog() throws -> String {
    assert(Thread.isMainThread)
    if let prepared = preparedCatalog { return prepared }
    let catalog = try catalogJSON()
    // The gate reads this same string at every call (AgentServer+Gate.swift).
    Self.noteArguments(in: catalog)
    // Nothing else forces the catalog and the dispatch table to agree, so
    // debug builds refuse to start the server on a mismatch. `make app`
    // builds Release, where an `assert` is compiled out — which would make
    // the one enforcement of the parity rule dead in every shipped build —
    // so Release logs the same message instead of failing silently.
    if let failure = Self.catalogParityFailure(catalog) {
        assertionFailure(failure)
        NSLog("Frame Job: %@", failure)
    }
    preparedCatalog = catalog
    return catalog
}

// MARK: - Dispatch

/// Executes one tool call and returns CallToolResult JSON. Errors are
/// in-band (`isError: true`) so the model can read and correct them.
///
/// Runs on the main thread for every tool but the `offMainTools`, which
/// the trampoline leaves on the server thread.
func execute(tool: String, argumentsJSON: String) -> String {
    assert(Thread.isMainThread || Self.offMainTools.contains(tool))
    let arguments =
        (try? JSONSerialization.jsonObject(with: Data(argumentsJSON.utf8)))
        as? [String: Any] ?? [:]
    do {
        return try dispatch(tool, arguments)
    } catch let error as ToolError {
        return errorResult(error.message)
    } catch {
        return errorResult(error.localizedDescription)
    }
}

private func dispatch(_ tool: String, _ a: [String: Any]) throws -> String {
    guard let handler = Self.handlers[tool] else {
        throw ToolError(message: "Unknown tool: \(tool)")
    }
    // The gate (AgentServer+Gate.swift): every key the caller wrote is
    // one this tool published, or the call is refused here by name before
    // the scope or any handler reads a thing. It is here for the reason
    // the scope read below is — the one place that holds the name and
    // the arguments of all eighty-nine.
    try Self.checkArgumentNames(tool, a)
    // The envelope's `scope` is read ONCE, here, because this is the only
    // place that holds both the tool's name and its arguments for all
    // eighty-nine of them — a read inside each handler would be
    // fifty-nine edit sites across the handler files, every one able to
    // forget. It is read for exactly the tools whose schema declares it
    // (`AgentCatalog.opNames`, the core's own op list), and a `scope` on
    // `get_project` or `export` is refused by the gate above as a key
    // those tools never published, where it used to be an ignored extra
    // key rather than a silently honoured one. The `defer`
    // is what makes the property a per-CALL value rather than state: the
    // next call starts with no scope of its own whatever this one asked
    // for or threw, and falls back to the view like any other.
    callScope = Self.opNames.contains(tool) ? try scopeArg(a) : nil
    defer { callScope = nil }
    return try handler(self)(a)
}

