// Tutorials TU1 and TU1b — the app's facts `tutorial_check.py` checks the
// guide's tutorials against (spec §11 TU-2, TU-7): the prepared catalog, the
// dev tools' names, the spotlight target table, the built menu bar, a fixture
// project's clips as the core writes them, and the bundled practice project
// as the app opens it.
//
// Compiled AS `main.swift` over every file in `app/Sources` but the app's own
// `main.swift`, with `-D FRAMEJOB_DEV_TOOLS`, through `swift_build.py`'s
// `build()` by `tutorial_check.py`.
//
//   tutorial_probe <work-dir> <practice-package>
//
// Prints exactly one stdout line:
//   ANSWER {"tools": {name: {"properties": {…}}}, "dev_tools": [sorted],
//           "targets": TutorialTargets.manifest(),
//           "menu": [{"path": [titles], "selector": str|null, "submenu": bool}],
//           "clips": [the fixture's clips, as the core writes them],
//           "practice": {"package": <path>,
//                        "clips": [{"id": n, …TutorialClipFacts.dictionary}],
//                        "media": [each media's resolved path, or null]}
//                       or {"error": "…"} when the practice read throws}
//   or ANSWER {"error": "…"} when a fact could not be read.
//
// The practice package is read through a fresh `ProjectDocument` and
// `PracticeProject.read(into:from:)`, the open path's own read, so its media
// are re-anchored at the package's `media/` as the app's open does it.
// Nothing binds the agent socket or opens a window: the fixture's media clip
// is a stand-in `add_media` descriptor with no file behind it.
import AppKit

final class ProbeDocumentController: NSDocumentController {
    override var defaultType: String? { ProjectDocument.projectTypeIdentifier }
}
_ = ProbeDocumentController()

let app = NSApplication.shared
app.setActivationPolicy(.prohibited)
let delegate = AppDelegate()
delegate.applicationWillFinishLaunching(
    Notification(name: NSApplication.willFinishLaunchingNotification, object: app))
AgentLane.prepareAtLaunch()

func answer(_ body: [String: Any]) -> Never {
    let data = (try? JSONSerialization.data(withJSONObject: body, options: [.sortedKeys]))
        ?? Data("{\"error\":\"the answer did not encode\"}".utf8)
    print("ANSWER " + (String(data: data, encoding: .utf8) ?? "{}"))
    fflush(stdout)
    exit(0)
}

func fail(_ reason: String) -> Never { answer(["error": reason]) }

// MARK: - The catalog

guard let catalog = AgentServer.shared.preparedCatalog,
      let tools = (try? JSONSerialization.jsonObject(with: Data(catalog.utf8))) as? [[String: Any]]
else { fail("no prepared catalog") }
var toolFacts: [String: Any] = [:]
for tool in tools {
    guard let name = tool["name"] as? String else { continue }
    let schema = tool["inputSchema"] as? [String: Any] ?? [:]
    toolFacts[name] = ["properties": schema["properties"] as? [String: Any] ?? [:]]
}

// MARK: - The menu bar, as `probe_sheets.swift`'s `runMenu` walks it

var menu: [[String: Any]] = []
func walk(_ items: NSMenu, _ path: [String]) {
    for item in items.items where !item.isSeparatorItem {
        let here = path + [item.title]
        menu.append([
            "path": here,
            "selector": item.action.map { NSStringFromSelector($0) as Any } ?? NSNull(),
            "submenu": item.submenu != nil,
        ])
        if let sub = item.submenu { walk(sub, here) }
    }
}
guard let mainMenu = NSApp.mainMenu else { fail("no main menu after willFinishLaunching") }
walk(mainMenu, [])

// MARK: - The fixture: a media clip with picture and sound, a text clip, a shape clip

let second: Ticks = 600_000
guard var project = ReelProject.new(width: 1920, height: 1080, fps: .thirty) else {
    fail("ReelProject.new answered nil")
}
func apply(_ op: ReelOp) {
    do {
        guard case .applied(let next) = try project.applying(op) else {
            fail("\(op.name) did not apply")
        }
        project = next
    } catch {
        fail("\(op.name): \(error)")
    }
}
guard let track = project.snapshot.tracks.first?.id else { fail("the new project has no track") }
apply(.addMedia(descriptor: MediaDescriptor(
    path: "/nonexistent/tutorial-probe.mov", kind: .video, duration: 4 * second, width: 1920,
    height: 1080, fps: .thirty, hasVideo: true, hasAudio: true)))
guard let media = project.snapshot.media.first?.id else { fail("add_media added nothing") }
apply(.addClip(track: track, media: media, at: 0))
apply(.addTextClip(track: track, at: 5 * second))
apply(.addShapeClip(track: track, at: 11 * second))
guard let document = (try? JSONSerialization.jsonObject(with: Data(project.json.utf8)))
        as? [String: Any],
      let clips = document["clips"] as? [[String: Any]], clips.count == 3
else { fail("the fixture's JSON did not read as three clips") }

// MARK: - The practice project, as the app opens it (spec §11 TU-7)

func practiceFacts() -> [String: Any] {
    let arguments = CommandLine.arguments
    guard arguments.count >= 3 else { return ["error": "no practice package argument"] }
    let package = URL(fileURLWithPath: arguments[2])
    let document = ProjectDocument()
    do {
        try PracticeProject.read(into: document, from: package)
    } catch {
        return ["package": package.path, "error": error.localizedDescription]
    }
    let snapshot = document.project.snapshot
    let clips: [[String: Any]] = snapshot.clips.map { clip in
        TutorialClipFacts(clip: clip, in: snapshot).dictionary.merging(["id": Int(clip.id)]) {
            mine, _ in mine
        }
    }
    let media: [Any] = snapshot.media.map { mediaURL(for: $0)?.path as Any? ?? NSNull() }
    return ["package": package.path, "clips": clips, "media": media]
}

answer([
    "practice": practiceFacts(),
    "tools": toolFacts,
    "dev_tools": AgentServer.devToolNames.sorted(),
    "targets": TutorialTargets.manifest(),
    "menu": menu,
    "clips": clips,
])
{
 "tools": {
  "set_selection": {"properties": {"clips": {"type": "array"}}},
  "set_audio": {"properties": {"clips": {"type": "array"}, "patch": {"type": "object"}, "scope": {"type": "integer"}}},
  "set_playhead": {"properties": {"t": {"type": "integer"}}},
  "split": {"properties": {"clips": {"type": "array"}, "at": {"type": "integer"}, "scope": {"type": "integer"}}},
  "add_track": {"properties": {"index": {"type": "integer"}, "name": {"type": "string"}}},
  "add_text_clip": {"properties": {"track": {"type": "integer"}, "at": {"type": "integer"}, "duration": {"type": "integer"}, "text": {"type": "object"}}},
  "set_transition_duration": {"properties": {"clip": {"type": "integer"}, "duration": {"type": "integer"}}},
  "set_range": {"properties": {"start": {"type": "integer"}, "end": {"type": "integer"}}},
  "export": {"properties": {"preset": {"type": "string"}, "path": {"type": "string"}, "range": {"type": "string", "enum": ["project", "in_out"]}}},
  "snapshot_ui": {"properties": {"window": {"type": "string"}}}
 },
 "dev_tools": ["snapshot_ui"],
 "targets": {
  "fixed": ["inspector.tab.document", "ruler", "sheet.export.add_to_queue", "timeline.bar.split", "timeline.clips", "toolbar.export", "toolbar.play"],
  "sections": {
   "audio.volume": {"tab": "clip", "sub_tab": "sound"},
   "text.content": {"tab": "clip", "sub_tab": "text"},
   "doc.canvas": {"tab": "document", "sub_tab": null}
  },
  "clip_refs": ["$selection", "$created"],
  "tabs": ["clip", "media", "document", "assistant"],
  "sub_tabs": ["text", "shape", "graphic", "picture", "color", "sound", "clip"]
 },
 "menu": [
  {"path": ["File"], "selector": "submenuAction:", "submenu": true},
  {"path": ["File", "Export…"], "selector": "exportProject:", "submenu": false},
  {"path": ["Edit"], "selector": "submenuAction:", "submenu": true},
  {"path": ["Edit", "Fancy"], "selector": "fancyThing:", "submenu": false},
  {"path": ["Clip"], "selector": "submenuAction:", "submenu": true},
  {"path": ["Clip", "Split"], "selector": "splitAtPlayhead:", "submenu": false},
  {"path": ["Clip", "Transition"], "selector": "submenuAction:", "submenu": true},
  {"path": ["Clip", "Transition", "Cross Dissolve"], "selector": "setTransitionKind:", "submenu": false},
  {"path": ["Mark"], "selector": "submenuAction:", "submenu": true},
  {"path": ["Mark", "Set In"], "selector": "setInPoint:", "submenu": false}
 ],
 "clips": [
  {"id": 2, "start": 0, "transition_in": null, "source": {"kind": "media"}, "audio": {"volume": 1.0}, "video": {"x": 0, "y": 0}},
  {"id": 3, "start": 3000000, "transition_in": null, "source": {"kind": "text"}, "text": {"content": "Title"}, "video": {"x": 0, "y": 0}}
 ],
 "practice": {
  "package": "/fixture/Practice Project.framejob",
  "clips": [
   {"id": 2, "has_sound": true, "has_pixels": true, "kind": "media", "follows_clip": false, "has_transition": false},
   {"id": 3, "has_sound": true, "has_pixels": true, "kind": "media", "follows_clip": true, "has_transition": false}
  ],
  "media": ["/fixture/Practice Project.framejob/media/Dawn.mov", "/fixture/Practice Project.framejob/media/Sea.mov"]
 }
}
{
 "selectors": {
  "exportProject:": {"verdict": "sheet"},
  "splitAtPlayhead:": {"verdict": "edit"},
  "setTransitionKind:": {"verdict": "edit"},
  "setInPoint:": {"verdict": "view"}
 }
}
