import Foundation

/// The tutorials the app runs (spec §11 TU-8 (1)): `Tutorials.json`, which
/// the build's "Write Tutorials" step writes with
/// `tools/tutorials/tutorial_extract.py`, read into typed tutorials and steps.
///
/// **Strict, per tutorial.** Anything outside TU-2 (2)–(9) — a key at any
/// level, a type, a value, a `reveal` whose section lives elsewhere, a
/// spotlight the target table lacks, a `$`-string no variable spells — refuses
/// THAT tutorial into `refused` with the reason, and the rest of the file
/// still reads. Only the top level throws. `tutorial_check.py` holds this
/// decoder to its own checker both ways through `tutorial_probe.swift`, so it
/// refuses nothing the checker accepts and accepts nothing it refuses. The
/// catalog, menu-bar, inventory and fixture-path checks are the checker's
/// alone (build time); one failing at run time is a refused Show Me.
enum TutorialJSON {
    /// A JSON `true`/`false` — not an `NSNumber` 0 or 1, which `as? Bool` takes.
    static func isBool(_ v: Any) -> Bool {
        guard let number = v as? NSNumber else { return false }
        return CFGetTypeID(number as CFTypeRef) == CFBooleanGetTypeID()
    }

    /// A JSON integer: a number that is not a boolean and has no fraction.
    static func isInt(_ v: Any) -> Bool {
        guard let number = v as? NSNumber, !isBool(v) else { return false }
        let value = number.doubleValue
        return value.isFinite && value == value.rounded() && abs(value) < 9.0e15
    }
}

struct TutorialModelError: LocalizedError {
    let message: String
    var errorDescription: String? { message }
}

struct TutorialLibrary {
    let pages: [TutorialPage]
    /// Tutorial id → the model's reason for refusing it.
    let refused: [String: String]

    /// Throws on the top level only: not an object, `format` not 1, `pages`
    /// not a list of pages.
    static func decode(_ data: Data) throws -> TutorialLibrary {
        guard let top = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any] else {
            throw TutorialModelError(message: "Tutorials.json is not a JSON object.")
        }
        guard let format = top["format"], TutorialJSON.isInt(format),
              (format as? NSNumber)?.intValue == 1
        else {
            throw TutorialModelError(message: "Tutorials.json's format is not 1.")
        }
        guard let rawPages = top["pages"] as? [Any] else {
            throw TutorialModelError(message: "Tutorials.json's pages is not a list.")
        }
        var pages: [TutorialPage] = []
        var refused: [String: String] = [:]
        for (index, raw) in rawPages.enumerated() {
            guard let page = raw as? [String: Any], let name = page["page"] as? String,
                  let title = page["title"] as? String, let list = page["tutorials"] as? [Any]
            else {
                throw TutorialModelError(
                    message: "Tutorials.json's page \(index + 1) is not {page, title, tutorials}.")
            }
            var tutorials: [Tutorial] = []
            for (number, entry) in list.enumerated() {
                let fallback = "\(name) tutorial \(number + 1)"
                let id = ((entry as? [String: Any])?["id"] as? String) ?? fallback
                do {
                    tutorials.append(try TutorialDecoder.tutorial(entry))
                } catch let error as TutorialModelError {
                    refused[id] = error.message
                }
            }
            pages.append(TutorialPage(page: name, title: title, tutorials: tutorials))
        }
        return TutorialLibrary(pages: pages, refused: refused)
    }

    private static var memo: TutorialLibrary?

    /// The bundle's `Tutorials.json`, read once. Main only.
    static func bundled() throws -> TutorialLibrary {
        if let memo { return memo }
        guard let url = Bundle.main.url(forResource: "Tutorials", withExtension: "json") else {
            throw TutorialModelError(message: "The app has no Tutorials.json.")
        }
        let library = try decode(try Data(contentsOf: url))
        memo = library
        return library
    }

    func tutorial(id: String) -> Tutorial? {
        for page in pages {
            if let found = page.tutorials.first(where: { $0.id == id }) { return found }
        }
        return nil
    }

    /// Every decoded tutorial's id, in guide order.
    var ids: [String] { pages.flatMap { $0.tutorials.map(\.id) } }
}

struct TutorialPage {
    let page: String
    let title: String
    let tutorials: [Tutorial]
}

struct Tutorial {
    let id, title, anchor: String
    /// The `needs.clip` filter, or nil for a tutorial that needs nothing.
    let needs: [String: Any]?
    let steps: [TutorialStep]
}

struct TutorialStep {
    let text: String
    let reveal: TutorialReveal?
    let spotlight: String?
    let wait: [TutorialCondition]
    let showMe: [TutorialShowMe]
    let optional: Bool
}

struct TutorialReveal: Equatable {
    let tab: InspectorTab
    let subTab: ClipSubTab?
    let section: String?
}

enum TutorialClipSet: String {
    case selection = "$selection", created = "$created"
}

enum TutorialRangeEdge: String {
    case start, end
}

enum TutorialCondition {
    case selection(min: Int, max: Int?, filter: [String: Any])
    case changed([String])
    case clips(added: Int, kind: String?)
    case playheadInside(TutorialClipSet)
    case rangeSet
    case rangeChanged(TutorialRangeEdge)
    case sheetExport
    case exportStarted
    case playing
}

enum TutorialShowMe {
    case tool(name: String, args: [String: Any])
    case menu(path: [String])
}

// MARK: - The decoder

/// TU-2's vocabulary, one refusal sentence per breach.
private enum TutorialDecoder {
    static let tutorialKeys: Set<String> = ["id", "title", "anchor", "needs", "steps"]
    static let stepKeys: Set<String> = ["text", "reveal", "spotlight", "wait", "show_me", "optional"]
    static let idPattern = "^[a-z][a-z0-9_]*(\\.[a-z][a-z0-9_]*)+$"
    static let plainVariables: Set<String> = ["$selection", "$created", "$playhead"]

    static func refuse(_ message: String) -> TutorialModelError {
        TutorialModelError(message: message)
    }

    static func tutorial(_ raw: Any) throws -> Tutorial {
        guard let object = raw as? [String: Any] else { throw refuse("a tutorial is not an object") }
        if let stranger = object.keys.sorted().first(where: { !tutorialKeys.contains($0) }) {
            throw refuse("unknown tutorial key \(stranger)")
        }
        guard let id = object["id"] as? String,
              id.range(of: idPattern, options: .regularExpression) != nil
        else { throw refuse("the id is not dotted lowercase words") }
        guard let title = object["title"] as? String, let anchor = object["anchor"] as? String
        else { throw refuse("the tutorial has no title or anchor") }
        var needs: [String: Any]?
        if let raw = object["needs"] {
            guard let dict = raw as? [String: Any], Set(dict.keys).isSubset(of: ["clip"]) else {
                throw refuse("needs is {clip: <filter>}")
            }
            if let clip = dict["clip"] { needs = try filter(clip, "needs.clip") }
        }
        guard let rawSteps = object["steps"] as? [Any], !rawSteps.isEmpty else {
            throw refuse("the tutorial has no steps")
        }
        var steps: [TutorialStep] = []
        for (index, raw) in rawSteps.enumerated() {
            do {
                steps.append(try step(raw))
            } catch let error as TutorialModelError {
                throw refuse("step \(index + 1): \(error.message)")
            }
        }
        return Tutorial(id: id, title: title, anchor: anchor, needs: needs, steps: steps)
    }

    static func step(_ raw: Any) throws -> TutorialStep {
        guard let object = raw as? [String: Any] else { throw refuse("the step is not an object") }
        if let stranger = object.keys.sorted().first(where: { !stepKeys.contains($0) }) {
            throw refuse("unknown step key \(stranger)")
        }
        guard let text = object["text"] as? String, !text.isEmpty else {
            throw refuse("the step has no sentence")
        }
        let reveal = try object["reveal"].map(Self.reveal)
        var spotlight: String?
        if let raw = object["spotlight"] { spotlight = try Self.spotlight(raw) }
        var wait: [TutorialCondition] = []
        if let raw = object["wait"] { wait = try Self.wait(raw) }
        var showMe: [TutorialShowMe] = []
        if let raw = object["show_me"] {
            let entries = (raw as? [Any]) ?? [raw]
            guard !entries.isEmpty else { throw refuse("show_me is an empty list") }
            showMe = try entries.map(Self.showMe)
        }
        var optional = false
        if let raw = object["optional"] {
            guard TutorialJSON.isBool(raw), (raw as? Bool) == true else {
                throw refuse("optional is not true")
            }
            optional = true
        }
        return TutorialStep(
            text: text, reveal: reveal, spotlight: spotlight, wait: wait, showMe: showMe,
            optional: optional)
    }

    /// A clip filter (TU-2 (3)), less any `extra` keys.
    static func filter(_ raw: Any, _ where_: String, extra: Set<String> = []) throws
        -> [String: Any] {
        guard let object = raw as? [String: Any] else { throw refuse("\(where_) is not an object") }
        var out: [String: Any] = [:]
        for key in object.keys.sorted() where !extra.contains(key) {
            guard let value = object[key] else { continue }
            guard TutorialClipFacts.keys.contains(key) else {
                throw refuse("\(where_) has an unknown key \(key)")
            }
            if key == "kind" {
                guard let kind = value as? String, TutorialClipFacts.kinds.contains(kind) else {
                    throw refuse("\(where_)'s kind is not a clip kind")
                }
            } else if !TutorialJSON.isBool(value) {
                throw refuse("\(where_)'s \(key) is not a boolean")
            }
            out[key] = value
        }
        return out
    }

    static func reveal(_ raw: Any) throws -> TutorialReveal {
        guard let object = raw as? [String: Any], let tabName = object["tab"] as? String,
              Set(object.keys).isSubset(of: ["tab", "sub_tab", "section"])
        else { throw refuse("reveal is {tab, sub_tab?, section?}") }
        guard let tab = InspectorTab.allCases.first(where: { $0.title.lowercased() == tabName })
        else { throw refuse("reveal.tab \(tabName) is not an inspector tab") }
        var subTab: ClipSubTab?
        if let raw = object["sub_tab"] {
            guard tab == .clip, let name = raw as? String, let found = ClipSubTab(rawValue: name)
            else { throw refuse("reveal.sub_tab is not a Clip tab sub-tab") }
            subTab = found
        }
        var section: String?
        if let raw = object["section"] {
            guard let id = raw as? String, let home = TutorialTargets.sections[id] else {
                throw refuse("reveal.section is not in the target table")
            }
            guard home == TutorialSectionHome(tab: tab, subTab: subTab) else {
                throw refuse("reveal.section \(id) lives on another tab or sub-tab")
            }
            section = id
        }
        return TutorialReveal(tab: tab, subTab: subTab, section: section)
    }

    static func spotlight(_ raw: Any) throws -> String {
        guard let name = raw as? String else { throw refuse("spotlight is not a string") }
        if TutorialTargets.fixed[name] != nil { return name }
        if name.hasPrefix(TutorialTargets.sectionPrefix),
           TutorialTargets.sections[String(name.dropFirst(TutorialTargets.sectionPrefix.count))]
            != nil
        {
            return name
        }
        if name.hasPrefix(TutorialTargets.clipPrefix),
           TutorialTargets.clipRefs.contains(String(name.dropFirst(TutorialTargets.clipPrefix.count)))
        {
            return name
        }
        throw refuse("unknown spotlight \(name)")
    }

    static func wait(_ raw: Any) throws -> [TutorialCondition] {
        guard let object = raw as? [String: Any], !object.isEmpty else {
            throw refuse("wait holds no condition")
        }
        return try object.keys.sorted().map { key in
            try condition(key, object[key] ?? NSNull())
        }
    }

    static func condition(_ key: String, _ value: Any) throws -> TutorialCondition {
        func isTrue(_ v: Any) -> Bool { TutorialJSON.isBool(v) && (v as? Bool) == true }
        switch key {
        case "selection":
            let filter = try Self.filter(value, "wait.selection", extra: ["min", "max"])
            let object = value as? [String: Any] ?? [:]
            var low = 1
            if let raw = object["min"] {
                guard TutorialJSON.isInt(raw), let n = (raw as? NSNumber)?.intValue, n >= 0 else {
                    throw refuse("wait.selection.min is not an integer ≥ 0")
                }
                low = n
            }
            var high: Int?
            if let raw = object["max"] {
                guard TutorialJSON.isInt(raw), let n = (raw as? NSNumber)?.intValue, n >= low else {
                    throw refuse("wait.selection.max is not an integer ≥ min")
                }
                high = n
            }
            return .selection(min: low, max: high, filter: filter)
        case "changed":
            let paths = (value as? String).map { [$0] } ?? (value as? [Any])?.compactMap { $0 as? String }
            guard let paths, !paths.isEmpty, paths.count == ((value as? [Any])?.count ?? 1),
                  paths.allSatisfy({ !$0.isEmpty })
            else { throw refuse("wait.changed is not a path or a list of paths") }
            return .changed(paths)
        case "clips":
            guard let object = value as? [String: Any],
                  Set(object.keys).isSubset(of: ["added", "kind"]),
                  let added = object["added"], TutorialJSON.isInt(added),
                  let count = (added as? NSNumber)?.intValue, count >= 1
            else { throw refuse("wait.clips is {added: int ≥ 1, kind?}") }
            var kind: String?
            if let raw = object["kind"] {
                guard let name = raw as? String, TutorialClipFacts.kinds.contains(name) else {
                    throw refuse("wait.clips.kind is not a clip kind")
                }
                kind = name
            }
            return .clips(added: count, kind: kind)
        case "playhead":
            guard let object = value as? [String: Any], object.count == 1,
                  let raw = object["inside"] as? String, let set = TutorialClipSet(rawValue: raw)
            else { throw refuse("wait.playhead is {inside: \"$selection\"|\"$created\"}") }
            return .playheadInside(set)
        case "range":
            if let object = value as? [String: Any], object.count == 1 {
                if let set = object["set"], isTrue(set) { return .rangeSet }
                if let raw = object["changed"] as? String, let edge = TutorialRangeEdge(rawValue: raw) {
                    return .rangeChanged(edge)
                }
            }
            throw refuse("wait.range is {set: true} or {changed: \"start\"|\"end\"}")
        case "sheet":
            guard (value as? String) == "export" else { throw refuse("wait.sheet is not \"export\"") }
            return .sheetExport
        case "export_started":
            guard isTrue(value) else { throw refuse("wait.export_started is not true") }
            return .exportStarted
        case "playing":
            guard isTrue(value) else { throw refuse("wait.playing is not true") }
            return .playing
        default:
            throw refuse("wait has an unknown condition \(key)")
        }
    }

    static func showMe(_ raw: Any) throws -> TutorialShowMe {
        guard let object = raw as? [String: Any] else { throw refuse("show_me is not an object") }
        if object["menu"] != nil {
            guard object.count == 1, let text = object["menu"] as? String else {
                throw refuse("a menu Show Me is exactly {\"menu\": \"A ▸ B\"}")
            }
            let path = text.components(separatedBy: "▸")
                .map { $0.trimmingCharacters(in: .whitespaces) }
            guard path.count >= 2, path.allSatisfy({ !$0.isEmpty }) else {
                throw refuse("a menu Show Me's path is not A ▸ B")
            }
