import json, sys
sys.path.insert(0, "/Users/kevingalligan/devel/framejob/.claude/worktrees/tutorial-handler/tools/proof")
from mcp import MCP, ToolError

m = MCP(sys.argv[1], timeout=120)
def short(s):
    return {k: s.get(k) for k in ("running", "step", "steps", "finished", "offers", "reveal_refused",
                                   "selection_at_start", "created", "completed", "last_show_me")}
for tid in sys.argv[2:]:
    m.call("new_project", practice=True)
    s = m.call("tutorial_start", id=tid)
    print(tid, "start", short(s))
    for _ in range(12):
        s = m.call("tutorial_state")
        if s.get("finished"):
            break
        act = "show_me" if "show_me" in s["offers"] else "next" if "next" in s["offers"] else "skip"
        try:
            s = m.call("tutorial_step", action=act)
        except ToolError as e:
            print("  refused", e); break
        print(" ", act, short(s))
        print("  inspector", {k: v for k, v in m.call("select_inspector_tab").items() if k != "project"})
    p = m.call("get_project")
    print("  clips", [(c["id"], c["track"], c["start"], c["duration"], (c.get("audio") or {}).get("volume"),
                      (c.get("text") or {}).get("content"), (c.get("video") or {}).get("y"),
                      c.get("transition_in")) for c in p["project"]["clips"]], p.get("in_out_range"))
    try:
        m.call("cancel_sheet")
    except ToolError as e:
        print("  cancel_sheet:", e)
    print("  close", m.call("close_project", discard=True))

